import {readFile,writeFile} from 'node:fs/promises';

const source=(await readFile(new URL('../public/image-rescue.js',import.meta.url),'utf8')).replace(/\r\n/g,'\n');
if(/<\/script/i.test(source))throw Error('Unsafe inline script terminator');
await writeFile(new URL('../lib/image-rescue-source.ts',import.meta.url),
  '// Generated by tools/build-image-rescue.mjs from public/image-rescue.js.\nexport const imageRescueSource = '+JSON.stringify(source)+';\n');
